import sys
import xml.etree.ElementTree as ET
import os

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except ET.ParseError:
        sys.exit(1)
    except IOError:
        sys.exit(1)

    username = sys.stdin.readline().strip()
    token = sys.stdin.readline().strip()
    file_path = sys.stdin.readline().strip()

    for user_elem in root.findall('user'):
        if user_elem.get('name') == username and user_elem.get('token') == token:
            for allow_elem in user_elem.findall('allow'):
                if allow_elem.get('path') == file_path:
                    try:
                        with open(file_path, 'r') as file:
                            print(file.read())
                        sys.exit(0)
                    except IOError:
                        sys.exit(2)

    sys.exit(1)

if __name__ == "__main__":
    main()
